use anyhow::{Context, Result};
use serde::Deserialize;
use serde_json::Value;

use crate::api::ApiClient;
use crate::executor::Executor;

#[derive(Deserialize, Debug, Clone)]
/// Represents a single file generated by the LLM.
pub struct FileEntry {
    /// The name of the file to be created.
    pub file_name: String,
    /// The source code content for the file.
    pub code: String,
    /// A shell command or script used to verify the correctness of this file.
    pub check: String,
}

#[derive(Deserialize, Debug)]
/// The complete response from the LLM, containing multiple file entries.
pub struct Answer {
    /// A list of files to be written to the workspace.
    pub files: Vec<FileEntry>,
}

impl Answer {
    /// Parses the LLM reply, handling potential Markdown code blocks.
    pub fn parse(reply: &str) -> Result<Self> {
        let cleaned = reply
            .trim()
            .strip_prefix("```json")
            .and_then(|s| s.strip_suffix("```"))
            .unwrap_or(reply)
            .trim();

        serde_json::from_str(cleaned).context("Failed to parse Answer JSON")
    }
}

pub const URL: &str = "https://arpanpathak.taildb9a39.ts.net/v1/chat/completions";
pub const MODEL: &str = "Qwen3.6-35B-A3B-NVFP4";
pub const MAX_ATTEMPTS: u32 = 5;
pub const WORK_DIR: &str = "harness_out";
pub const SKILL: &str = include_str!("../../skills/keep-it-simple-code/SKILL.md");

pub const FORMAT: &str = r#"Reply with only this JSON object:
{"files": [{"file_name": "main.rs", "code": "...", "check": "..."}]}
The program must assert its own result, so a wrong answer exits with an error."#;

/// The current state of the agentic loop.
pub enum State {
    /// The agent is currently asking the LLM for a solution.
    Ask,
    /// The agent is checking the LLM's response.
    Check(String),
    /// The agent is attempting to fix a failure.
    Fix(anyhow::Error),
    /// The agent has successfully completed the task.
    Pass,
    /// The agent has exhausted all attempts and given up.
    GiveUp,
}

/// The main orchestration engine for the agentic loop.
pub struct Harness {
    /// The client used to communicate with the LLM.
    pub client: ApiClient,
    /// The history of the conversation.
    pub conversation: Vec<Value>,
    /// The current attempt number.
    pub attempt: u32,
}

impl Harness {
    /// Creates a new `Harness` instance.
    ///
    /// # Arguments
    /// * `task` - The natural language description of the task to perform.
    /// * `api_key` - The authentication key for the LLM API.
    pub fn new(task: String, api_key: String) -> Self {
        let conversation = vec![
            serde_json::json!({ "role": "system", "content": format!("{SKILL}\n\n{FORMAT}") }),
            serde_json::json!({ "role": "user", "content": task }),
        ];

        Self {
            client: ApiClient::new(URL.to_string(), api_key),
            conversation,
            attempt: 0,
        }
    }

    /// Starts the agentic loop and runs until completion or failure.
    ///
    /// # Returns
    /// A `Result` indicating whether the loop finished successfully or encountered an error.
    pub fn run(&mut self) -> Result<()> {
        let mut state = State::Ask;

        loop {
            state = match state {
                State::Ask => self.ask(),
                State::Check(reply) => self.check(reply),
                State::Fix(failure) => self.fix(&failure),
                State::Pass => return Ok(()),
                State::GiveUp => anyhow::bail!("no passing program after {MAX_ATTEMPTS} attempts"),
            };
        }
    }

    /// Sends a request to the LLM to get a new solution.
    ///
    /// # Returns
    /// The next `State` in the loop.
    fn ask(&mut self) -> State {
        self.attempt += 1;
        println!("--- attempt {}", self.attempt);

        match self.client.send(&self.conversation) {
            Ok(reply) => {
                let path = format!("{WORK_DIR}/reply-{}.txt", self.attempt);
                std::fs::write(&path, &reply).ok();
                println!("raw reply: {path}");
                State::Check(reply)
            }
            Err(failure) => State::Fix(failure),
        }
    }

    /// Validates the LLM's response by parsing, saving, and running checks.
    ///
    /// # Arguments
    /// * `reply` - The raw string response from the LLM.
    ///
    /// # Returns
    /// The next `State` in the loop.
    fn check(&mut self, reply: String) -> State {
        let outcome = Answer::parse(&reply)
            .and_then(Executor::save)
            .and_then(Executor::run)
            .and_then(Executor::report);

        self.conversation.push(serde_json::json!({ "role": "assistant", "content": reply }));

        match outcome {
            Ok(()) => State::Pass,
            Err(failure) => State::Fix(failure),
        }
    }

    /// Provides feedback to the LLM about a failure and requests a fix.
    ///
    /// # Arguments
    /// * `failure` - The error that occurred during the check phase.
    ///
    /// # Returns
    /// The next `State` in the loop.
    fn fix(&mut self, failure: &anyhow::Error) -> State {
        eprintln!("{failure:#}");

        let feedback = format!("That failed:\n{failure:#}\nFix it and reply with the JSON again.");
        self.conversation.push(serde_json::json!({ "role": "user", "content": feedback }));

        if self.attempt == MAX_ATTEMPTS {
            return State::GiveUp;
        }

        State::Ask
    }
}
